package org.marketreview.nativeapp;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.function.BooleanSupplier;

/** Dedicated cache/library. BLOBs are read in 64KiB chunks, never through a >2MiB CursorWindow row. */
final class NewsStore {
 static final int APP=0x4e575631;final File file;NewsStore(File file){this.file=file;}
 static long scalar(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){NewsModel.need(c.moveToFirst(),"资讯库查询失败");return c.getLong(0);}}
 SQLiteDatabase open(boolean write,BooleanSupplier cancel)throws Exception{NewsModel.active(cancel);if(write&&!file.exists()){File parent=file.getAbsoluteFile().getParentFile();NewsModel.need(parent.isDirectory()||parent.mkdirs(),"资讯库目录不可创建");}SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getPath(),null,SQLiteDatabase.NO_LOCALIZED_COLLATORS|(write?SQLiteDatabase.OPEN_READWRITE|SQLiteDatabase.CREATE_IF_NECESSARY:SQLiteDatabase.OPEN_READONLY));try{try(Cursor c=db.rawQuery("PRAGMA busy_timeout=100",null)){c.moveToFirst();}long app=scalar(db,"PRAGMA application_id");NewsModel.need(app==APP||write&&app==0&&scalar(db,"SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")==0,"不是资讯专用库，原库未改动");NewsModel.need(scalar(db,"PRAGMA user_version")<=1,"资讯库版本高于程序");if(write){db.execSQL("PRAGMA synchronous=FULL");db.beginTransaction();try{db.execSQL("CREATE TABLE IF NOT EXISTS records(key TEXT PRIMARY KEY,digest TEXT NOT NULL,payload BLOB NOT NULL)");db.execSQL("CREATE TABLE IF NOT EXISTS imports(digest TEXT PRIMARY KEY,applied_at TEXT NOT NULL)");db.execSQL("PRAGMA application_id="+APP);db.execSQL("PRAGMA user_version=1");commit(db,cancel);}finally{db.endTransaction();}}return db;}catch(Exception e){db.close();throw e;}}
 static void commit(SQLiteDatabase db,BooleanSupplier cancel){NewsModel.active(cancel);db.setTransactionSuccessful();}
 JSONObject record(SQLiteDatabase db,String key,BooleanSupplier cancel)throws Exception{NewsModel.active(cancel);long length;String digest;try(Cursor c=db.rawQuery("SELECT length(payload),digest FROM records WHERE key=?",new String[]{key})){if(!c.moveToFirst())return null;length=c.getLong(0);digest=c.getString(1);}NewsModel.need(length>0&&length<=NewsModel.MAX,"资讯数据长度无效");ByteArrayOutputStream bytes=new ByteArrayOutputStream((int)length);for(int start=1;start<=length;start+=65536){NewsModel.active(cancel);try(Cursor c=db.rawQuery("SELECT substr(payload,?,65536) FROM records WHERE key=?",new String[]{String.valueOf(start),key})){NewsModel.need(c.moveToFirst(),"资讯分块读取失败");byte[] part=c.getBlob(0);NewsModel.need(part!=null&&part.length==Math.min(65536,length-start+1),"资讯分块长度不符");bytes.write(part);}}byte[] raw=bytes.toByteArray();NewsModel.need(raw.length==length&&NewsModel.hash(raw).equals(digest),"资讯数据摘要不符");return new JSONObject(new String(raw,StandardCharsets.UTF_8));}
 void put(SQLiteDatabase db,String key,JSONObject data,BooleanSupplier cancel)throws Exception{NewsModel.active(cancel);byte[] bytes=data.toString().getBytes(StandardCharsets.UTF_8);NewsModel.need(bytes.length>0&&bytes.length<=NewsModel.MAX,"资讯保存超过8MiB，不截断");ContentValues v=new ContentValues();v.put("key",key);v.put("digest",NewsModel.hash(bytes));v.put("payload",bytes);NewsModel.need(db.insertWithOnConflict("records",null,v,SQLiteDatabase.CONFLICT_REPLACE)!=-1,"资讯保存失败");JSONObject readback=record(db,key,cancel);NewsModel.need(readback.toString().equals(data.toString()),"资讯写后读回不符");}
 JSONObject archive(SQLiteDatabase db,BooleanSupplier cancel)throws Exception{JSONObject a=record(db,"archive",cancel);if(a==null)return NewsModel.empty();NewsModel.validateArchive(a);return a;}
 synchronized JSONObject archive(BooleanSupplier cancel)throws Exception{NewsModel.active(cancel);if(!file.exists())return NewsModel.empty();try(SQLiteDatabase db=open(false,cancel)){return archive(db,cancel);}}
 JSONObject writeArchive(SQLiteDatabase db,JSONObject input,long expected,BooleanSupplier cancel)throws Exception{NewsModel.validateArchive(input);NewsModel.need(expected>=0&&expected<9007199254740991L&&archive(db,cancel).getLong("revision")==expected,"本机资讯档案已被修改，请重读后保存");JSONObject next=new JSONObject(input.toString()).put("revision",expected+1).put("savedAt",NewsModel.time(Instant.now()));NewsModel.validateArchive(next);put(db,"archive",next,cancel);return next;}
 synchronized JSONObject saveArchive(JSONObject input,long expected,BooleanSupplier cancel)throws Exception{NewsModel.validateArchive(input);try(SQLiteDatabase db=open(true,cancel)){db.beginTransaction();try{JSONObject next=writeArchive(db,input,expected,cancel);commit(db,cancel);return next;}finally{db.endTransaction();}}}
 synchronized JSONObject importPreview(JSONObject preview,BooleanSupplier cancel)throws Exception{NewsModel.validateArchive(preview.getJSONObject("archive"));String digest=preview.getString("digest");NewsModel.need(digest.matches("[0-9a-f]{64}"),"导入摘要无效");try(SQLiteDatabase db=open(true,cancel)){db.beginTransaction();try{try(Cursor c=db.rawQuery("SELECT 1 FROM imports WHERE digest=?",new String[]{digest})){if(c.moveToFirst()){JSONObject a=archive(db,cancel);commit(db,cancel);return a;}}JSONObject next=writeArchive(db,preview.getJSONObject("archive"),preview.getLong("expectedRevision"),cancel);ContentValues v=new ContentValues();v.put("digest",digest);v.put("applied_at",NewsModel.time(Instant.now()));NewsModel.need(db.insertOrThrow("imports",null,v)!=-1,"资讯导入回执失败");commit(db,cancel);return next;}finally{db.endTransaction();}}}
 synchronized JSONObject cache(JSONObject query,BooleanSupplier cancel)throws Exception{String key=NewsModel.queryKey(query);JSONObject out=new JSONObject();NewsModel.active(cancel);if(!file.exists())return out;try(SQLiteDatabase db=open(false,cancel)){JSONObject snapshot=record(db,"cache:"+key,cancel),attempt=record(db,"attempt:"+key,cancel);if(snapshot!=null){NewsModel.validateSnapshot(snapshot);NewsModel.need(snapshot.getString("key").equals(key)&&snapshot.getBoolean("complete"),"不是当前范围完整资讯缓存");out.put("snapshot",snapshot);}if(attempt!=null)out.put("attempt",attempt);}return out;}
 synchronized void saveSnapshot(JSONObject snapshot,BooleanSupplier cancel)throws Exception{NewsModel.validateSnapshot(snapshot);NewsModel.need(snapshot.getBoolean("complete"),"部分资讯不覆盖旧完整缓存");String key=snapshot.getString("key");try(SQLiteDatabase db=open(true,cancel)){db.beginTransaction();try{JSONObject prior=record(db,"cache:"+key,cancel);NewsModel.need(prior==null||!NewsModel.instant(snapshot.getString("fetchedAt")).isBefore(NewsModel.instant(prior.getString("fetchedAt"))),"旧回调不能覆盖新资讯集合");put(db,"cache:"+key,snapshot,cancel);put(db,"attempt:"+key,new JSONObject().put("checkedAt",snapshot.getString("fetchedAt")).put("error","").put("status","complete-requested-range"),cancel);commit(db,cancel);}finally{db.endTransaction();}}}
 synchronized void failure(JSONObject query,String message,BooleanSupplier cancel)throws Exception{NewsModel.need(!message.isEmpty()&&message.length()<=4000,"失败信息无效");String key=NewsModel.queryKey(query);try(SQLiteDatabase db=open(true,cancel)){db.beginTransaction();try{put(db,"attempt:"+key,new JSONObject().put("checkedAt",NewsModel.time(Instant.now())).put("error",message).put("status","source-unavailable"),cancel);commit(db,cancel);}finally{db.endTransaction();}}}
 synchronized JSONObject article(JSONObject item,BooleanSupplier cancel)throws Exception{NewsModel.validateItem(item);JSONObject out=new JSONObject();if(!file.exists())return out;try(SQLiteDatabase db=open(false,cancel)){JSONObject data=record(db,"article:"+item.getString("id"),cancel),attempt=record(db,"article-attempt:"+item.getString("id"),cancel);if(data!=null){NewsModel.need(data.getString("itemId").equals(item.getString("id")),"缓存正文身份不符");NewsModel.validateArticle(data.getJSONObject("article"),item);out.put("article",data.getJSONObject("article"));}if(attempt!=null)out.put("attempt",attempt);}return out;}
 synchronized void saveArticle(JSONObject item,JSONObject article,BooleanSupplier cancel)throws Exception{NewsModel.validateItem(item);NewsModel.validateArticle(article,item);String id=item.getString("id");try(SQLiteDatabase db=open(true,cancel)){db.beginTransaction();try{if(article.getString("status").equals("available"))put(db,"article:"+id,new JSONObject().put("itemId",id).put("article",article),cancel);put(db,"article-attempt:"+id,new JSONObject().put("checkedAt",article.getString("fetchedAt")).put("error",article.getString("status").equals("available")?"":article.getString("message")).put("status",article.getString("status")),cancel);commit(db,cancel);}finally{db.endTransaction();}}}
}
